CREATE OR REPLACE FUNCTION contour.guard_collector(tenant uuid, collector uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'authority mutation requires read committed' USING ERRCODE = '25001';
    END IF;
    IF tenant IS NULL OR collector IS NULL OR tenant IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'authority mutation context mismatch' USING ERRCODE = '42501';
    END IF;
    IF NOT pg_catalog.pg_try_advisory_xact_lock(contour.collector_lock_key(tenant, collector)) THEN
        RAISE EXCEPTION 'collector authority busy' USING ERRCODE = '40001';
    END IF;
END $function$

CREATE OR REPLACE FUNCTION contour.end_origin(tenant uuid, kind text, target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE started timestamptz; at_time timestamptz; collector uuid; lifecycle_key uuid;
BEGIN
    PERFORM contour.begin_origin_operation(tenant);
    IF kind='lifecycle_closed' THEN
        lifecycle_key := target;
        SELECT l.enrolled_at INTO started FROM contour.origin_lifecycles l WHERE l.tenant_id=tenant AND l.lifecycle_id=target;
    ELSIF kind='credential_revoked' THEN
        SELECT c.enrolled_at,c.lifecycle_id INTO started,lifecycle_key FROM contour.origin_credentials c WHERE c.tenant_id=tenant AND c.credential_id=target;
    ELSIF kind='grant_revoked' THEN
        SELECT g.collector_id INTO collector FROM contour.origin_observer_grants g WHERE g.tenant_id=tenant AND g.grant_id=target;
        IF collector IS NULL THEN RAISE EXCEPTION 'target unavailable' USING ERRCODE='23514'; END IF;
        PERFORM contour.lock_origin_collector(tenant,collector);
        SELECT g.granted_at,g.lifecycle_id INTO started,lifecycle_key FROM contour.origin_observer_grants g WHERE g.tenant_id=tenant AND g.grant_id=target;
    ELSE
        RAISE EXCEPTION 'invalid terminal event' USING ERRCODE='23514';
    END IF;
    IF started IS NULL THEN RAISE EXCEPTION 'target unavailable' USING ERRCODE='23514'; END IF;
    at_time := contour.origin_server_time();
    IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) OR at_time < started OR at_time < contour.origin_history_highwater(tenant,lifecycle_key) THEN
        RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514';
    END IF;
    INSERT INTO contour.origin_terminal_events VALUES (tenant,kind,
        CASE WHEN kind='lifecycle_closed' THEN target END,
        CASE WHEN kind='credential_revoked' THEN target END,
        CASE WHEN kind='grant_revoked' THEN target END,at_time);
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'terminal event already recorded' USING ERRCODE='23505';
END $function$

CREATE OR REPLACE FUNCTION contour.enroll_origin_credential(tenant uuid, credential uuid, lifecycle uuid, leaf bytea)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE started timestamptz; at_time timestamptz;
BEGIN
    PERFORM contour.begin_origin_operation(tenant);
    PERFORM contour.lock_origin_credential(leaf);
    SELECT l.enrolled_at INTO started FROM contour.origin_lifecycles l WHERE l.tenant_id=tenant AND l.lifecycle_id=lifecycle
      AND NOT EXISTS (SELECT 1 FROM contour.origin_terminal_events e WHERE e.tenant_id=tenant AND e.lifecycle_id=lifecycle AND e.event_kind='lifecycle_closed');
    IF started IS NULL THEN RAISE EXCEPTION 'origin unavailable' USING ERRCODE='23514'; END IF;
    at_time := contour.origin_server_time();
    IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) OR at_time < started OR at_time < contour.origin_history_highwater(tenant,lifecycle) THEN
        RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514';
    END IF;
    INSERT INTO contour.origin_credentials VALUES (tenant,credential,lifecycle,leaf,at_time);
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'credential unavailable' USING ERRCODE='23505';
END $function$

CREATE OR REPLACE FUNCTION contour.enroll_origin(tenant uuid, lifecycle uuid, project uuid, service uuid, environment uuid, deployment uuid, instance uuid, kind text, evidence bytea)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE at_time timestamptz;
BEGIN
    PERFORM contour.begin_origin_operation(tenant);
    IF kind IS DISTINCT FROM 'trusted_platform_v1' OR pg_catalog.octet_length(evidence) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION 'invalid origin evidence' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM contour.workload_instances i WHERE i.tenant_id=tenant
        AND i.instance_id=instance AND i.project_id=project AND i.service_id=service
        AND i.environment_id=environment AND i.deployment_id=deployment) THEN
        RAISE EXCEPTION 'origin instance unavailable' USING ERRCODE='23514';
    END IF;
    at_time := contour.origin_server_time();
    IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) THEN RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514'; END IF;
    INSERT INTO contour.origin_lifecycles VALUES (tenant,lifecycle,project,service,environment,deployment,instance,kind,evidence,at_time);
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'origin identity unavailable' USING ERRCODE='23505';
END $function$

CREATE OR REPLACE FUNCTION contour.grant_origin_observer(tenant uuid, grant_id uuid, lifecycle uuid, source uuid, collector uuid, project uuid, service uuid, environment uuid, deployment uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE started timestamptz; at_time timestamptz;
BEGIN
    PERFORM contour.begin_origin_operation(tenant);
    PERFORM contour.lock_origin_collector(tenant,collector);
    SELECT l.enrolled_at INTO started FROM contour.origin_lifecycles l WHERE l.tenant_id=tenant AND l.lifecycle_id=lifecycle
      AND NOT EXISTS (SELECT 1 FROM contour.origin_terminal_events e WHERE e.tenant_id=tenant AND e.lifecycle_id=lifecycle AND e.event_kind='lifecycle_closed');
    IF started IS NULL OR NOT EXISTS (SELECT 1 FROM contour.sources s WHERE s.tenant_id=tenant
       AND s.source_id=source AND s.collector_id=collector AND s.project_id=project AND s.service_id=service
       AND s.environment_id=environment AND s.deployment_id=deployment) THEN
        RAISE EXCEPTION 'origin or observer unavailable' USING ERRCODE='23514';
    END IF;
    IF EXISTS (SELECT 1 FROM contour.origin_observer_grants g WHERE g.tenant_id=tenant AND g.lifecycle_id=lifecycle
       AND g.source_id=source AND g.collector_id=collector AND g.project_id=project AND g.service_id=service
       AND g.environment_id=environment AND g.deployment_id=deployment
       AND NOT EXISTS (SELECT 1 FROM contour.origin_terminal_events e WHERE e.tenant_id=tenant AND e.grant_id=g.grant_id AND e.event_kind='grant_revoked')) THEN
        RAISE EXCEPTION 'active grant exists' USING ERRCODE='23505';
    END IF;
    at_time := contour.origin_server_time();
    IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) OR at_time < started OR at_time < contour.origin_history_highwater(tenant,lifecycle) THEN
        RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514';
    END IF;
    INSERT INTO contour.origin_observer_grants VALUES (tenant,grant_id,lifecycle,source,collector,project,service,environment,deployment,at_time);
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'grant unavailable' USING ERRCODE='23505';
END $function$

CREATE OR REPLACE FUNCTION contour.human_origin_operation(tenant uuid, target_project uuid, target_service uuid, target_environment uuid, operation uuid, filter_project uuid, filter_service uuid, filter_environment uuid, filter_deployment uuid, filter_instance uuid)
 RETURNS TABLE(origin_project_id uuid, origin_service_id uuid, origin_environment_id uuid, origin_deployment_id uuid, instance_id uuid, truncated boolean, last_seen text, visibility text, completeness text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE h contour.catalog_origin_heads; w contour.observation_windows; payload bytea; envelope jsonb; checked_record jsonb; n integer := 0;
 seen_batches text[] := ARRAY[]::text[]; batch_key text;
BEGIN
 IF tenant IS NULL OR tenant IS DISTINCT FROM contour.tenant_context() OR target_project IS NULL OR target_service IS NULL OR target_environment IS NULL OR operation IS NULL OR NOT ((filter_project IS NULL AND filter_service IS NULL AND filter_environment IS NULL AND filter_deployment IS NULL AND filter_instance IS NULL) OR (filter_project IS NOT NULL AND filter_service IS NOT NULL AND filter_environment IS NOT NULL AND filter_deployment IS NOT NULL AND filter_instance IS NOT NULL)) THEN
   RAISE EXCEPTION 'invalid catalog scope' USING ERRCODE='42501'; END IF;
 FOR h IN SELECT x.* FROM contour.catalog_origin_heads x
   WHERE (x.tenant_id,x.project_id,x.service_id,x.environment_id,x.operation_id)=(tenant,target_project,target_service,target_environment,operation)
     AND (filter_project IS NULL OR (x.origin_project_id,x.origin_service_id,x.origin_environment_id,x.origin_deployment_id,x.instance_id)=(filter_project,filter_service,filter_environment,filter_deployment,filter_instance))
   ORDER BY x.origin_project_id,x.origin_service_id,x.origin_environment_id,x.origin_deployment_id,x.instance_id LIMIT 33
 LOOP
   n:=n+1;
   IF n=33 THEN origin_project_id:=NULL; origin_service_id:=NULL; origin_environment_id:=NULL; origin_deployment_id:=NULL; instance_id:=NULL; truncated:=true; last_seen:=NULL; visibility:=NULL; completeness:=NULL; RETURN NEXT; RETURN; END IF;
   SELECT x.* INTO STRICT w FROM contour.observation_windows x
    WHERE (x.tenant_id,x.collector_id,x.batch_id,x.record_id)=(tenant,h.collector_id,h.batch_id,h.record_id)
      AND (x.project_id,x.service_id,x.environment_id,x.operation_id)=(target_project,target_service,target_environment,operation)
      AND x.last_seen::timestamptz=h.observed_at;
   IF NOT EXISTS (SELECT 1 FROM contour.catalog_origin_projection p
      WHERE (p.tenant_id,p.collector_id,p.batch_id,p.record_id,p.proof_id,p.origin_project_id,p.origin_service_id,p.origin_environment_id,p.origin_deployment_id,p.instance_id)
       =(tenant,h.collector_id,h.batch_id,h.record_id,h.proof_id,h.origin_project_id,h.origin_service_id,h.origin_environment_id,h.origin_deployment_id,h.instance_id)) THEN
      RAISE EXCEPTION 'origin head mismatch' USING ERRCODE='23514'; END IF;
   batch_key:=h.collector_id::text || '/' || h.batch_id::text;
   SELECT p.checked_batch INTO STRICT payload FROM contour.ingestion_payloads p
     WHERE (p.tenant_id,p.collector_id,p.batch_id)=(tenant,h.collector_id,h.batch_id)
       AND p.payload_format=2 AND pg_catalog.octet_length(p.checked_batch) BETWEEN 1 AND 1048576;
   envelope:=pg_catalog.convert_from(payload,'UTF8')::jsonb;
   IF NOT (batch_key=ANY(seen_batches)) THEN
     -- The ingress verifier preserves historical seeding behavior; human reads
     -- additionally require a bidirectional attribution/witness match throughout
     -- the retained checked batch before disclosing any verified identity.
     IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(envelope->'records') AS item(value)
       LEFT JOIN contour.ingestion_v2_metadata m
         ON (m.tenant_id,m.collector_id,m.batch_id,m.record_id::text)=(tenant,h.collector_id,h.batch_id,item.value->'record'->>'record_id')
       WHERE (item.value->'origin_witness'->>'kind'='downstream_mtls_leaf_sha256_v1' AND m.attribution_class IS DISTINCT FROM 'verified_origin_v1')
          OR (item.value->'origin_witness'->>'kind'='unattributed' AND m.attribution_class IS DISTINCT FROM 'unattributed')) THEN
       RAISE EXCEPTION 'origin attribution mismatch' USING ERRCODE='23514'; END IF;
     IF EXISTS (WITH verified AS MATERIALIZED (
         SELECT * FROM contour.catalog_origin_mapping(tenant,h.collector_id,h.batch_id,payload)
       )
       SELECT 1 FROM ((SELECT p.record_id,p.proof_id,p.origin_project_id,p.origin_service_id,p.origin_environment_id,p.origin_deployment_id,p.instance_id
         FROM contour.catalog_origin_projection p WHERE (p.tenant_id,p.collector_id,p.batch_id)=(tenant,h.collector_id,h.batch_id)
       EXCEPT SELECT * FROM verified)
       UNION ALL (SELECT * FROM verified
       EXCEPT SELECT p.record_id,p.proof_id,p.origin_project_id,p.origin_service_id,p.origin_environment_id,p.origin_deployment_id,p.instance_id
         FROM contour.catalog_origin_projection p WHERE (p.tenant_id,p.collector_id,p.batch_id)=(tenant,h.collector_id,h.batch_id))) AS differences) THEN
       RAISE EXCEPTION 'origin projection mismatch' USING ERRCODE='23514'; END IF;
     seen_batches:=pg_catalog.array_append(seen_batches,batch_key);
   END IF;
   SELECT item.value->'record' INTO STRICT checked_record
     FROM pg_catalog.jsonb_array_elements(envelope->'records') AS item(value)
     WHERE item.value->'record'->>'record_id'=h.record_id::text;
   IF w.last_seen IS DISTINCT FROM checked_record->>'last_seen'
      OR w.visibility IS DISTINCT FROM checked_record->>'visibility'
      OR w.completeness IS DISTINCT FROM checked_record->>'completeness' THEN
     RAISE EXCEPTION 'origin observation mismatch' USING ERRCODE='23514'; END IF;
   origin_project_id:=h.origin_project_id; origin_service_id:=h.origin_service_id; origin_environment_id:=h.origin_environment_id;
   origin_deployment_id:=h.origin_deployment_id; instance_id:=h.instance_id; truncated:=false;
   last_seen:=w.last_seen; visibility:=w.visibility; completeness:=w.completeness; RETURN NEXT;
 END LOOP;
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION 'origin history unavailable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION contour.catalog_origin_requires_canonical(tenant uuid, collector uuid, batch uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE origin_writer boolean;
BEGIN
    IF tenant IS NULL OR collector IS NULL OR batch IS NULL OR tenant IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'origin context mismatch' USING ERRCODE='42501';
    END IF;
    SELECT p.origin_writer_provenance INTO STRICT origin_writer FROM contour.ingestion_payloads p
      WHERE (p.tenant_id,p.collector_id,p.batch_id)=(tenant,collector,batch) AND p.payload_format=2;
    PERFORM contour.catalog_origin_absent(tenant,collector,batch);
    RETURN origin_writer;
EXCEPTION WHEN no_data_found OR too_many_rows THEN
    RAISE EXCEPTION 'origin history unavailable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION contour.accept_causal_batch(t uuid, runtime uuid, ep numeric, peer_leaf bytea, verified_grant_digest bytea, canonical_batch bytea)
 RETURNS TABLE(receipt_id uuid, accepted_at timestamp with time zone, duplicate boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE binding contour.causal_runtime_bindings; s contour.causal_sessions; old contour.causal_inbox_batches; j jsonb; stored jsonb; bid uuid; now_at timestamptz; used bigint; n integer;
BEGIN
 PERFORM contour.begin_origin_operation(t);
 SELECT * INTO binding FROM contour.causal_runtime_bindings b WHERE b.tenant_id=t AND b.runtime_id=runtime;
 IF NOT FOUND THEN RAISE EXCEPTION 'session unavailable' USING ERRCODE='23514'; END IF;
 PERFORM contour.lock_origin_credential(binding.export_leaf_sha256);
 PERFORM contour.lock_origin_collector(t,binding.collector_id);
 SELECT * INTO s FROM contour.causal_sessions x WHERE x.tenant_id=t AND x.runtime_id=runtime AND x.epoch=ep;
 now_at:=clock_timestamp();
 IF NOT FOUND OR peer_leaf IS DISTINCT FROM binding.export_leaf_sha256 OR peer_leaf IS DISTINCT FROM (s.claim).export_leaf OR verified_grant_digest IS DISTINCT FROM (s.claim).grant_digest OR NOT contour.causal_session_locked(s.claim,ep,now_at)
 THEN RAISE EXCEPTION 'session unavailable' USING ERRCODE='23514'; END IF;
 j:=contour.causal_parse(canonical_batch);
 IF (j->>'tenant_id')::uuid IS DISTINCT FROM t OR (j->>'runtime_id')::uuid IS DISTINCT FROM runtime OR (j->>'session_epoch')::numeric IS DISTINCT FROM ep OR octet_length(canonical_batch)>(s.claim).max_batch_bytes OR jsonb_array_length(j->'events')>(s.claim).max_batch_events
 THEN RAISE EXCEPTION 'batch scope or limit mismatch' USING ERRCODE='23514'; END IF;
 bid:=(j->>'batch_id')::uuid;
 SELECT * INTO old FROM contour.causal_inbox_batches x WHERE (x.tenant_id,x.runtime_id,x.session_epoch,x.batch_id)=(t,runtime,ep,bid);
 IF FOUND THEN
  -- Only stored-byte data/semantic failures become integrity failures. Do not
  -- catch operational errors, cancellations, or malformed incoming requests.
  BEGIN
   stored:=contour.causal_parse(old.canonical_batch);
  EXCEPTION WHEN data_exception OR check_violation THEN
   RAISE EXCEPTION 'stored causal batch corrupted' USING ERRCODE='23514';
  END;
  IF old.batch_digest IS DISTINCT FROM sha256(convert_to(E'apicontour/causal-events/1\n','UTF8')||old.canonical_batch)
  OR (stored->>'tenant_id')::uuid IS DISTINCT FROM t OR (stored->>'runtime_id')::uuid IS DISTINCT FROM runtime OR (stored->>'session_epoch')::numeric IS DISTINCT FROM ep OR (stored->>'batch_id')::uuid IS DISTINCT FROM bid
  OR old.event_count IS DISTINCT FROM jsonb_array_length(stored->'events') OR old.receipt_id IS NULL OR old.accepted_at IS NULL OR NOT isfinite(old.accepted_at) OR old.receipt_digest IS DISTINCT FROM contour.causal_receipt_digest(t,runtime,ep,bid,old.receipt_id,old.accepted_at,old.batch_digest,old.event_count)
  OR EXISTS (SELECT 1 FROM ((SELECT * FROM contour.causal_decoded_events(stored) EXCEPT SELECT x.seq,x.event_id,x.kind,x.root,x.activity,x.parent,x.attempt,x.marker_digest,x.first_missing_seq,x.last_missing_seq,x.reason,x.event_digest FROM contour.causal_inbox_events x WHERE (x.tenant_id,x.runtime_id,x.session_epoch,x.batch_id)=(t,runtime,ep,bid)) UNION ALL
  (SELECT x.seq,x.event_id,x.kind,x.root,x.activity,x.parent,x.attempt,x.marker_digest,x.first_missing_seq,x.last_missing_seq,x.reason,x.event_digest FROM contour.causal_inbox_events x WHERE (x.tenant_id,x.runtime_id,x.session_epoch,x.batch_id)=(t,runtime,ep,bid) EXCEPT SELECT * FROM contour.causal_decoded_events(stored))) difference)
  THEN RAISE EXCEPTION 'stored causal batch corrupted' USING ERRCODE='23514'; END IF;
  IF old.canonical_batch IS DISTINCT FROM canonical_batch THEN RAISE EXCEPTION 'causal batch conflict' USING ERRCODE='23505'; END IF;
  IF NOT contour.causal_session_locked(s.claim,ep,now_at) THEN RAISE EXCEPTION 'session unavailable at final lease check' USING ERRCODE='23514'; END IF;
  RETURN QUERY SELECT old.receipt_id,old.accepted_at,true; RETURN;
 END IF;
 -- A session admits at most 4,096 events in total. This is a work bound,
 -- independent of the 1 GiB logical quota; it can stop admission much earlier.
 -- Session renewal does not transfer this history or establish continuity.
 -- Q serializes this namespace. The ordered, bounded read uses the primary
 -- (tenant,runtime,epoch,seq) key; it never ignores an admitted history row.
 SELECT count(*) INTO n FROM (SELECT x.seq FROM contour.causal_inbox_events x
  WHERE (x.tenant_id,x.runtime_id,x.session_epoch)=(t,runtime,ep) ORDER BY x.seq LIMIT 4097) bounded;
 IF n+jsonb_array_length(j->'events')>4096 THEN
  RAISE EXCEPTION 'causal session history limit exhausted' USING ERRCODE='54000',CONSTRAINT='causal_session_history_limit';
 END IF;
 -- Materialize the bounded, indexed history once. The worst case is 500 x
 -- 4,096 fact comparisons, including both LOSS arrival orders; no DAG search.
 IF EXISTS (WITH history AS MATERIALIZED (
  SELECT x.* FROM contour.causal_inbox_events x WHERE (x.tenant_id,x.runtime_id,x.session_epoch)=(t,runtime,ep)
  ORDER BY x.seq LIMIT 4096), incoming AS MATERIALIZED (
  SELECT * FROM contour.causal_decoded_events(j))
  SELECT 1 FROM history x CROSS JOIN incoming e WHERE
   (x.seq=e.seq OR x.event_id=e.event_id OR
    (x.kind='loss' AND e.seq BETWEEN x.first_missing_seq AND x.last_missing_seq) OR
    (e.kind='loss' AND x.seq BETWEEN e.first_missing_seq AND e.last_missing_seq) OR
    (x.kind='root' AND e.kind='root' AND x.root=e.root) OR
    (x.kind='root' AND e.kind='delivery' AND x.root=e.activity) OR
    (e.kind='root' AND x.kind='delivery' AND e.root=x.activity) OR
    (x.kind='root' AND e.kind='attempt' AND x.root=e.activity AND e.root<>e.activity) OR
    (e.kind='root' AND x.kind='attempt' AND e.root=x.activity AND x.root<>x.activity) OR
    (x.kind IN ('delivery','attempt') AND e.kind IN ('delivery','attempt') AND x.activity=e.activity AND x.root<>e.root) OR
    (x.kind='delivery' AND e.kind='delivery' AND x.activity=e.activity AND x.parent<>e.parent) OR
    (x.kind='attempt' AND e.kind='attempt' AND x.attempt=e.attempt AND (x.root,x.activity,x.marker_digest)<>(e.root,e.activity,e.marker_digest))))
 THEN RAISE EXCEPTION 'causal fact conflict' USING ERRCODE='23505'; END IF;
 INSERT INTO contour.origin_logical_usage(tenant_id,used_bytes) VALUES(t,0) ON CONFLICT(tenant_id) DO NOTHING;
 SELECT x.used_bytes INTO STRICT used FROM contour.origin_logical_usage x WHERE x.tenant_id=t FOR UPDATE;
 IF octet_length(canonical_batch)>1073741824-used THEN RAISE EXCEPTION 'origin logical quota exhausted' USING ERRCODE='54000',CONSTRAINT='origin_logical_quota_exhausted'; END IF;
 old.receipt_id:=gen_random_uuid(); old.accepted_at:=clock_timestamp();
 old.batch_digest:=sha256(convert_to(E'apicontour/causal-events/1\n','UTF8')||canonical_batch);
 old.event_count:=jsonb_array_length(j->'events');
 INSERT INTO contour.causal_inbox_batches(tenant_id,runtime_id,session_epoch,batch_id,canonical_batch,batch_digest,event_count,receipt_id,accepted_at,receipt_digest)
 VALUES(t,runtime,ep,bid,canonical_batch,old.batch_digest,old.event_count,old.receipt_id,old.accepted_at,contour.causal_receipt_digest(t,runtime,ep,bid,old.receipt_id,old.accepted_at,old.batch_digest,old.event_count)) RETURNING * INTO old;
 INSERT INTO contour.causal_inbox_events SELECT t,runtime,ep,bid,x.* FROM contour.causal_decoded_events(j) x;
 UPDATE contour.origin_logical_usage SET used_bytes=used+octet_length(canonical_batch) WHERE tenant_id=t;
 IF NOT contour.causal_session_locked(s.claim,ep,now_at) THEN RAISE EXCEPTION 'session unavailable at final lease check' USING ERRCODE='23514'; END IF;
 RETURN QUERY SELECT old.receipt_id,old.accepted_at,false;
END $function$

CREATE OR REPLACE FUNCTION contour.check_causal_session(t uuid, runtime uuid, ep numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE b contour.causal_runtime_bindings; s contour.causal_sessions; now_at timestamptz;
BEGIN
 PERFORM contour.begin_origin_operation(t);
 SELECT * INTO b FROM contour.causal_runtime_bindings WHERE tenant_id=t AND runtime_id=runtime;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM contour.lock_origin_credential(b.export_leaf_sha256);
 PERFORM contour.lock_origin_collector(t,b.collector_id);
 SELECT * INTO s FROM contour.causal_sessions WHERE tenant_id=t AND runtime_id=runtime AND epoch=ep;
 IF NOT FOUND THEN RETURN false; END IF;
 now_at:=pg_catalog.clock_timestamp();
 RETURN contour.causal_session_locked(s.claim,ep,now_at);
END $function$

CREATE OR REPLACE FUNCTION contour.issue_causal_session(x contour.causal_session_claim)
 RETURNS TABLE(epoch numeric, issued_at timestamp with time zone, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE now_at timestamptz; old contour.causal_sessions; highest numeric; latest contour.causal_sessions; deadline timestamptz;
BEGIN
 PERFORM contour.begin_origin_operation(x.tenant_id);
 PERFORM contour.lock_origin_credential(x.export_leaf);
 PERFORM contour.lock_origin_collector(x.tenant_id,x.collector_id);
 IF x.runtime_id IS NULL OR x.source_id IS NULL OR x.project_id IS NULL OR x.service_id IS NULL OR x.environment_id IS NULL OR x.deployment_id IS NULL OR x.instance_id IS NULL OR x.lifecycle_id IS NULL OR x.nonce IS NULL
 OR x.grant_revision IS NULL OR x.grant_revision<>trunc(x.grant_revision) OR x.grant_revision NOT BETWEEN 1 AND 18446744073709551615
 OR x.policy_revision IS NULL OR x.policy_revision<>trunc(x.policy_revision) OR x.policy_revision NOT BETWEEN 1 AND 18446744073709551615
 OR x.grant_digest IS NULL OR octet_length(x.grant_digest)<>32 OR x.policy_envelope IS NULL OR octet_length(x.policy_envelope) NOT BETWEEN 1 AND 1048576
 OR x.grant_issued IS NULL OR NOT isfinite(x.grant_issued) OR x.grant_expires IS NULL OR NOT isfinite(x.grant_expires)
 OR x.policy_issued IS NULL OR NOT isfinite(x.policy_issued) OR x.policy_expires IS NULL OR NOT isfinite(x.policy_expires)
 OR x.grant_expires<=x.grant_issued OR x.grant_expires-x.grant_issued>interval '15 minutes' OR x.policy_expires<=x.policy_issued
 OR x.ttl_microseconds IS NULL OR x.ttl_microseconds NOT BETWEEN 1 AND 900000000
 OR x.max_batch_events IS NULL OR x.max_batch_events NOT BETWEEN 1 AND 500 OR x.max_batch_bytes IS NULL OR x.max_batch_bytes NOT BETWEEN 1 AND 1048576
 OR x.queue_bytes IS NULL OR x.queue_bytes NOT BETWEEN 1 AND 268435456 OR x.queue_ttl_seconds IS NULL OR x.queue_ttl_seconds NOT BETWEEN 1 AND 86400
 THEN RAISE EXCEPTION 'invalid session assertion' USING ERRCODE='23514'; END IF;
 now_at:=pg_catalog.clock_timestamp();
 SELECT * INTO latest FROM contour.causal_sessions s WHERE s.tenant_id=x.tenant_id AND s.runtime_id=x.runtime_id ORDER BY s.epoch DESC LIMIT 1;
 IF now_at IS NULL OR NOT isfinite(now_at) OR (latest.epoch IS NOT NULL AND now_at<latest.issued_at) OR NOT contour.causal_runtime_authority_locked(x,now_at)
 THEN RAISE EXCEPTION 'session unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO old FROM contour.causal_sessions s WHERE s.tenant_id=x.tenant_id AND s.runtime_id=x.runtime_id AND s.nonce=x.nonce;
 IF FOUND THEN
  IF old.claim IS NOT DISTINCT FROM x AND contour.causal_session_locked(x,old.epoch,now_at) THEN
   RETURN QUERY SELECT old.epoch,old.issued_at,old.expires_at; RETURN;
  END IF;
  RAISE EXCEPTION 'nonce unavailable' USING ERRCODE='23505';
 END IF;
 IF latest.epoch IS NOT NULL AND (x.grant_revision<(latest.claim).grant_revision OR (x.grant_revision=(latest.claim).grant_revision AND x.grant_digest IS DISTINCT FROM (latest.claim).grant_digest))
 THEN RAISE EXCEPTION 'grant revision unavailable' USING ERRCODE='23514'; END IF;
 highest:=coalesce(latest.epoch,0);
 IF highest>=18446744073709551615 THEN RAISE EXCEPTION 'session epoch exhausted' USING ERRCODE='22003'; END IF;
 deadline:=least(now_at + x.ttl_microseconds * interval '1 microsecond',x.grant_expires,x.policy_expires);
 IF NOT isfinite(deadline) OR deadline<=now_at THEN RAISE EXCEPTION 'invalid session lease' USING ERRCODE='23514'; END IF;
 INSERT INTO contour.causal_sessions VALUES (x.tenant_id,x.runtime_id,highest+1,x.nonce,x,now_at,deadline);
 -- Recheck after INSERT and its triggers/constraints; if work consumed the
 -- bounded lease, raising here rolls the row, nonce and revision back together.
 IF NOT contour.causal_session_locked(x,highest+1,now_at) THEN
  RAISE EXCEPTION 'session unavailable at final lease check' USING ERRCODE='23514';
 END IF;
 -- A caller can still delay COMMIT. An atomic admission consumer must recheck
 -- the session under its locks in the transaction containing the admission.
 RETURN QUERY SELECT highest+1,now_at,deadline;
END $function$

CREATE OR REPLACE FUNCTION contour.end_causal_runtime(t uuid, runtime uuid, kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r contour.causal_runtime_bindings; at_time timestamptz;
BEGIN
 PERFORM contour.begin_origin_operation(t);
 IF kind NOT IN ('runtime_closed','export_revoked') OR kind IS NULL THEN RAISE EXCEPTION 'runtime unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO r FROM contour.causal_runtime_bindings WHERE tenant_id=t AND runtime_id=runtime;
 IF NOT FOUND THEN RAISE EXCEPTION 'runtime unavailable' USING ERRCODE='23514'; END IF;
 PERFORM contour.lock_origin_credential(r.export_leaf_sha256);
 PERFORM contour.lock_origin_collector(t,r.collector_id);
 IF EXISTS (SELECT 1 FROM contour.causal_runtime_terminal_events z WHERE z.tenant_id=t AND z.runtime_id=runtime) THEN RAISE EXCEPTION 'runtime unavailable' USING ERRCODE='23505'; END IF;
 at_time:=pg_catalog.clock_timestamp();
 IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) OR at_time<r.enrolled_at OR at_time<contour.origin_history_highwater(t,r.lifecycle_id) THEN RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514'; END IF;
 INSERT INTO contour.causal_runtime_terminal_events VALUES (t,runtime,kind,at_time);
END $function$

CREATE OR REPLACE FUNCTION contour.enroll_causal_runtime(t uuid, runtime uuid, c uuid, src uuid, p uuid, s uuid, e uuid, d uuid, i uuid, lifecycle uuid, profile uuid, artifact bytea, leaf bytea)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE existing contour.causal_runtime_bindings; at_time timestamptz;
BEGIN
 PERFORM contour.begin_origin_operation(t);
 PERFORM contour.lock_origin_credential(leaf);
 PERFORM contour.lock_origin_collector(t,c);
 IF runtime IS NULL OR lifecycle IS NULL OR profile IS DISTINCT FROM '00000000-0000-4000-8000-000000000501'::uuid OR artifact IS DISTINCT FROM decode('b0bcc91455463d2dd48c438292abe1063ed7d3430459ead5ec48423c9ba1b510','hex') THEN RAISE EXCEPTION 'runtime unavailable' USING ERRCODE='23514'; END IF;
 IF NOT contour.causal_legacy_authorized(t,c,src,p,s,e,d,i) OR NOT EXISTS (
  SELECT 1 FROM contour.causal_runtime_profiles x WHERE x.tenant_id=t AND x.profile_id=profile AND x.artifact_sha256=artifact
   AND x.point_kind='node_in' AND x.method='POST' AND x.route='/run' AND x.technique='runtime' AND x.parser_profile='http_json_v1')
 OR NOT EXISTS (SELECT 1 FROM contour.origin_lifecycles l WHERE l.tenant_id=t AND l.lifecycle_id=lifecycle
   AND l.project_id=p AND l.service_id=s AND l.environment_id=e AND l.deployment_id=d AND l.instance_id=i
   AND NOT EXISTS (SELECT 1 FROM contour.origin_terminal_events z WHERE z.tenant_id=t AND z.lifecycle_id=lifecycle AND z.event_kind='lifecycle_closed')
   AND EXISTS (SELECT 1 FROM contour.origin_credentials oc WHERE oc.tenant_id=t AND oc.lifecycle_id=lifecycle
     AND NOT EXISTS (SELECT 1 FROM contour.origin_terminal_events z WHERE z.tenant_id=t AND z.credential_id=oc.credential_id AND z.event_kind='credential_revoked')))
 THEN RAISE EXCEPTION 'runtime unavailable' USING ERRCODE='23514'; END IF;
 at_time:=pg_catalog.clock_timestamp();
 IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) OR at_time<contour.origin_history_highwater(t,lifecycle) THEN RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514'; END IF;
 SELECT * INTO existing FROM contour.causal_runtime_bindings WHERE tenant_id=t AND runtime_id=runtime;
 IF FOUND THEN
  IF existing.collector_id=c AND existing.source_id=src AND existing.project_id=p AND existing.service_id=s AND existing.environment_id=e
    AND existing.deployment_id=d AND existing.instance_id=i AND existing.lifecycle_id=lifecycle AND existing.profile_id=profile
    AND existing.artifact_sha256=artifact AND existing.export_leaf_sha256=leaf AND existing.enrolled_at<=at_time
    AND EXISTS (SELECT 1 FROM contour.causal_leaf_reservations WHERE leaf_sha256=leaf AND leaf_class='export')
    AND NOT EXISTS (SELECT 1 FROM contour.causal_runtime_terminal_events z WHERE z.tenant_id=t AND z.runtime_id=runtime)
  THEN RETURN runtime; END IF;
  RAISE EXCEPTION 'runtime unavailable' USING ERRCODE='23505';
 END IF;
 INSERT INTO contour.causal_leaf_reservations VALUES (leaf,'export');
 INSERT INTO contour.causal_runtime_bindings VALUES (t,runtime,c,src,p,s,e,d,i,lifecycle,profile,artifact,leaf,at_time);
 RETURN runtime;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'runtime unavailable' USING ERRCODE='23505';
END $function$

CREATE OR REPLACE FUNCTION contour.register_causal_profile(t uuid, profile uuid, artifact bytea)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE existing contour.causal_runtime_profiles;
BEGIN
 PERFORM contour.begin_origin_operation(t);
 IF profile IS DISTINCT FROM '00000000-0000-4000-8000-000000000501'::uuid OR artifact IS DISTINCT FROM decode('b0bcc91455463d2dd48c438292abe1063ed7d3430459ead5ec48423c9ba1b510','hex') THEN RAISE EXCEPTION 'profile unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO existing FROM contour.causal_runtime_profiles WHERE tenant_id=t AND profile_id=profile;
 IF FOUND THEN
  IF existing.artifact_sha256=artifact AND existing.point_kind='node_in' AND existing.method='POST' AND existing.route='/run'
     AND existing.technique='runtime' AND existing.parser_profile='http_json_v1' THEN RETURN profile; END IF;
  RAISE EXCEPTION 'profile unavailable' USING ERRCODE='23505';
 END IF;
 INSERT INTO contour.causal_runtime_profiles VALUES (t,profile,artifact,'node_in','POST','/run','runtime','http_json_v1',pg_catalog.clock_timestamp());
 RETURN profile;
END $function$

CREATE OR REPLACE FUNCTION contour.verify_origin_batch_proofs(tenant uuid, collector uuid, batch uuid, canonical_checked_payload bytea)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE envelope jsonb; b contour.ingestion_batches;
BEGIN
    envelope := contour.parse_origin_batch(tenant,collector,batch,canonical_checked_payload);
    SELECT x.* INTO STRICT b FROM contour.ingestion_batches x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND pg_catalog.octet_length(x.request_digest)=32;
    RETURN contour.verify_origin_batch_parsed(tenant,collector,batch,b,envelope);
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_text_representation OR character_not_in_repertoire THEN
    RAISE EXCEPTION 'origin batch unavailable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION contour.verify_origin_proof(tenant uuid, proof uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE p contour.origin_proofs; b contour.ingestion_batches; m contour.ingestion_v2_metadata;
    payload bytea; envelope jsonb; wrapper jsonb;
BEGIN
    IF tenant IS NULL OR tenant IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'origin context mismatch' USING ERRCODE='42501';
    END IF;
    SELECT x.* INTO STRICT p FROM contour.origin_proofs x WHERE x.tenant_id=tenant AND x.proof_id=proof
      AND pg_catalog.octet_length(x.canonical_proof) BETWEEN 1 AND 4096
      AND pg_catalog.octet_length(x.request_digest)=32 AND pg_catalog.octet_length(x.leaf_sha256)=32
      AND pg_catalog.octet_length(x.platform_evidence_sha256)=32 AND pg_catalog.octet_length(x.parser_profile) BETWEEN 1 AND 64;
    SELECT x.* INTO STRICT b FROM contour.ingestion_batches x WHERE x.tenant_id=tenant AND x.collector_id=p.collector_id AND x.batch_id=p.batch_id AND pg_catalog.octet_length(x.request_digest)=32;
    SELECT x.* INTO STRICT m FROM contour.ingestion_v2_metadata x WHERE x.tenant_id=tenant AND x.collector_id=p.collector_id AND x.batch_id=p.batch_id AND x.record_id=p.record_id
      AND pg_catalog.octet_length(x.request_digest)=32 AND pg_catalog.octet_length(x.parser_profile) BETWEEN 1 AND 64 AND x.attribution_class IN ('unattributed','verified_origin_v1');
    SELECT x.checked_batch INTO STRICT payload FROM contour.ingestion_payloads x WHERE x.tenant_id=tenant AND x.collector_id=p.collector_id AND x.batch_id=p.batch_id AND x.payload_format=2 AND pg_catalog.octet_length(x.checked_batch) BETWEEN 1 AND 1048576;
    envelope := contour.parse_origin_batch(tenant,p.collector_id,p.batch_id,payload);
    SELECT x.value INTO STRICT wrapper FROM pg_catalog.jsonb_array_elements(envelope->'records') x(value)
      WHERE x.value->'record'->>'record_id'=p.record_id::text;
    RETURN contour.verify_origin_proof_parsed(tenant,p,b,m,wrapper);
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_text_representation OR character_not_in_repertoire THEN
    RAISE EXCEPTION 'origin proof unavailable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION contour.begin_origin_ingress(tenant uuid, collector uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE at_time timestamptz; current_epoch bigint; floor_time timestamptz;
BEGIN
    -- This guard refuses any preheld advisory lock, including session locks,
    -- and acquires Q first. The collector gate is then held through transaction end.
    PERFORM contour.begin_origin_operation(tenant);
    PERFORM contour.lock_origin_collector(tenant,collector);
    at_time := contour.origin_server_time();
    IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) THEN
        RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514';
    END IF;
    PERFORM contour.ensure_origin_tenant_state(tenant);
    SELECT s.epoch,s.clock_floor INTO current_epoch,floor_time FROM contour.origin_tenant_state s WHERE s.tenant_id=tenant;
    IF floor_time IS NOT NULL AND at_time < floor_time THEN
        RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514';
    END IF;
    INSERT INTO contour.origin_ingress_context
        VALUES (pg_catalog.txid_current(),pg_catalog.pg_backend_pid(),tenant,collector,at_time,current_epoch);
END $function$

CREATE OR REPLACE FUNCTION contour.origin_insert_authorized(tenant uuid, collector uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF tenant IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'origin context mismatch' USING ERRCODE='42501';
    END IF;
    PERFORM contour.require_origin_ingress(tenant,collector);
    RETURN true;
END $function$

CREATE OR REPLACE FUNCTION contour.origin_retry_requires_canonical(tenant uuid, collector uuid, batch uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF tenant IS NULL OR collector IS NULL OR batch IS NULL OR tenant IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'origin context mismatch' USING ERRCODE='42501';
    END IF;
    PERFORM contour.require_origin_ingress(tenant,collector);
    RETURN contour.catalog_origin_requires_canonical(tenant,collector,batch);
END $function$

CREATE OR REPLACE FUNCTION contour.resolve_origin_record(tenant uuid, collector uuid, batch uuid, record uuid, canonical_checked_payload bytea)
 RETURNS contour.origin_resolution
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE envelope jsonb; wrapper jsonb; m contour.ingestion_v2_metadata;
BEGIN
    PERFORM contour.require_origin_ingress(tenant,collector);
    envelope := contour.parse_origin_batch(tenant,collector,batch,canonical_checked_payload);
    SELECT x.value INTO STRICT wrapper FROM pg_catalog.jsonb_array_elements(envelope->'records') x(value)
      WHERE x.value->'record'->>'record_id'=record::text;
    SELECT x.* INTO STRICT m FROM contour.ingestion_v2_metadata x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND x.record_id=record
      AND pg_catalog.octet_length(x.request_digest)=32 AND pg_catalog.octet_length(x.parser_profile) BETWEEN 1 AND 64 AND x.attribution_class IN ('unattributed','verified_origin_v1');
    RETURN contour.resolve_origin_record_checked(tenant,collector,m,wrapper->'origin_witness');
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_text_representation OR character_not_in_repertoire THEN
    RAISE EXCEPTION 'checked record unavailable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION contour.write_origin_batch_proofs(tenant uuid, collector uuid, batch uuid, canonical_checked_payload bytea)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE envelope jsonb; wrapper jsonb; witness jsonb; m contour.ingestion_v2_metadata;
    b contour.ingestion_batches; p contour.origin_proofs; resolution contour.origin_resolution;
    floor_time timestamptz; at_time timestamptz; used bigint; n integer := 0; size_bytes bigint;
    set_digest bytea;
BEGIN
    PERFORM contour.require_origin_ingress(tenant,collector);
    envelope := contour.parse_origin_batch(tenant,collector,batch,canonical_checked_payload);
    SELECT x.* INTO STRICT b FROM contour.ingestion_batches x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND pg_catalog.octet_length(x.request_digest)=32;
    IF EXISTS (SELECT 1 FROM contour.origin_batch_proof_completion x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch) THEN
        PERFORM contour.verify_origin_batch_parsed(tenant,collector,batch,b,envelope);
        RETURN 0;
    END IF;
    IF EXISTS (SELECT 1 FROM contour.origin_proofs x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch) THEN
        RAISE EXCEPTION 'origin completion missing' USING ERRCODE='23514';
    END IF;
    FOR wrapper IN SELECT x.value FROM pg_catalog.jsonb_array_elements(envelope->'records') x(value) LOOP
        witness := wrapper->'origin_witness';
        SELECT x.* INTO STRICT m FROM contour.ingestion_v2_metadata x
          WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND x.record_id::text=wrapper->'record'->>'record_id'
            AND pg_catalog.octet_length(x.request_digest)=32 AND pg_catalog.octet_length(x.parser_profile) BETWEEN 1 AND 64 AND x.attribution_class IN ('unattributed','verified_origin_v1');
        IF witness = '{"kind":"unattributed"}'::jsonb THEN CONTINUE; END IF;
        resolution := contour.resolve_origin_record_checked(tenant,collector,m,witness);
        SELECT s.clock_floor INTO STRICT floor_time FROM contour.origin_tenant_state s WHERE s.tenant_id=tenant FOR UPDATE;
        at_time := contour.origin_server_time();
        IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) OR at_time < resolution.context_time
           OR at_time < m.accepted_at OR (floor_time IS NOT NULL AND at_time < floor_time) THEN
            RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514';
        END IF;
        p := NULL;
        p.tenant_id:=tenant; p.proof_id:=pg_catalog.gen_random_uuid(); p.collector_id:=collector;
        p.batch_id:=batch; p.record_id:=m.record_id; p.request_digest:=m.request_digest;
        p.accepted_at:=m.accepted_at; p.proof_accepted_at:=at_time;
        p.source_id:=m.source_id; p.project_id:=m.project_id; p.service_id:=m.service_id;
        p.environment_id:=m.environment_id; p.deployment_id:=m.deployment_id;
        p.policy_revision:=m.policy_revision; p.parser_profile:=m.parser_profile;
        p.lifecycle_id:=resolution.lifecycle_id; p.credential_id:=resolution.credential_id; p.grant_id:=resolution.grant_id;
        p.origin_project_id:=resolution.origin_project_id; p.origin_service_id:=resolution.origin_service_id;
        p.origin_environment_id:=resolution.origin_environment_id; p.origin_deployment_id:=resolution.origin_deployment_id;
        p.instance_id:=resolution.instance_id; p.leaf_sha256:=pg_catalog.decode(witness->>'leaf_sha256','hex');
        p.platform_evidence_sha256:=resolution.platform_evidence_sha256;
        p.lifecycle_epoch:=resolution.lifecycle_epoch; p.credential_epoch:=resolution.credential_epoch;
        p.grant_epoch:=resolution.grant_epoch; p.context_epoch:=resolution.context_epoch; p.context_time:=resolution.context_time;
        p.canonical_proof:=contour.encode_origin_proof(p);
        size_bytes:=pg_catalog.octet_length(p.canonical_proof);
        INSERT INTO contour.origin_logical_usage (tenant_id,used_bytes) VALUES (tenant,0) ON CONFLICT (tenant_id) DO NOTHING;
        SELECT u.used_bytes INTO STRICT used FROM contour.origin_logical_usage u WHERE u.tenant_id=tenant FOR UPDATE;
        IF size_bytes > 1073741824 - used THEN
            RAISE EXCEPTION 'origin logical quota exhausted' USING ERRCODE='54000', CONSTRAINT='origin_logical_quota_exhausted';
        END IF;
        INSERT INTO contour.origin_proofs SELECT (p).*;
        UPDATE contour.origin_logical_usage SET used_bytes=used+size_bytes WHERE tenant_id=tenant;
        UPDATE contour.origin_tenant_state SET clock_floor=at_time WHERE tenant_id=tenant;
        n:=n+1;
    END LOOP;
    IF n>0 THEN
        -- This statement sees proofs inserted earlier in this transaction.
        SELECT pg_catalog.sha256(pg_catalog.convert_to(E'apicontour/origin-proof-set/1\n' ||
          coalesce(pg_catalog.string_agg(x.record_id::text || ':' || x.proof_id::text || ':' ||
            pg_catalog.encode(pg_catalog.sha256(x.canonical_proof),'hex'), ',' ORDER BY x.record_id),''),'UTF8'))
          INTO set_digest FROM contour.origin_proofs x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch;
        INSERT INTO contour.origin_batch_proof_completion (tenant_id,collector_id,batch_id,request_digest,receipt_id,accepted_at,proof_count,proof_set_digest)
        VALUES (tenant,collector,batch,b.request_digest,b.receipt_id,b.accepted_at,n,set_digest);
    END IF;
    RETURN n;
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_text_representation OR character_not_in_repertoire THEN
    RAISE EXCEPTION 'origin batch unavailable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION contour.lock_collector(tenant uuid, collector uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'collector lock requires read committed' USING ERRCODE = '25001';
    END IF;
    IF tenant IS NULL OR collector IS NULL OR tenant IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'collector lock context mismatch' USING ERRCODE = '42501';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(contour.collector_lock_key(tenant, collector));
END $function$

CREATE OR REPLACE FUNCTION contour.assign_origin_fact_epoch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE at_time timestamptz; state_epoch bigint; floor_time timestamptz;
BEGIN
    PERFORM contour.ensure_origin_tenant_state(NEW.tenant_id);
    IF TG_TABLE_NAME IN ('origin_lifecycles','origin_credentials') THEN at_time := NEW.enrolled_at;
    ELSIF TG_TABLE_NAME='origin_observer_grants' THEN at_time := NEW.granted_at;
    ELSE at_time := NEW.event_at; END IF;
    SELECT s.epoch,s.clock_floor INTO state_epoch,floor_time FROM contour.origin_tenant_state s WHERE s.tenant_id=NEW.tenant_id FOR UPDATE;
    IF at_time IS NULL OR NOT pg_catalog.isfinite(at_time) OR (floor_time IS NOT NULL AND at_time < floor_time) THEN
        RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514';
    END IF;
    IF state_epoch = 9223372036854775807 THEN
        RAISE EXCEPTION 'origin epoch exhausted' USING ERRCODE='54000';
    END IF;
    NEW.fact_epoch := state_epoch + 1;
    UPDATE contour.origin_tenant_state SET epoch=NEW.fact_epoch,clock_floor=at_time WHERE tenant_id=NEW.tenant_id;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION contour.authority_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
            OR NEW.collector_id IS DISTINCT FROM OLD.collector_id THEN
            RAISE EXCEPTION 'authority identity immutable' USING ERRCODE = '23514';
        END IF;
        IF TG_TABLE_NAME = 'source_authorization' THEN
            IF NEW.source_id IS DISTINCT FROM OLD.source_id THEN
                RAISE EXCEPTION 'source identity immutable' USING ERRCODE = '23514';
            END IF;
        ELSE
            IF (OLD.active_revision IS NOT NULL AND (NEW.active_revision IS NULL
                OR NEW.active_revision < OLD.active_revision))
                OR (OLD.revoked_at IS NOT NULL AND NEW IS DISTINCT FROM OLD) THEN
                RAISE EXCEPTION 'authority rollback forbidden' USING ERRCODE = '23514';
            END IF;
        END IF;
    END IF;
    PERFORM contour.guard_collector(NEW.tenant_id, NEW.collector_id);
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION contour.begin_origin_operation(tenant uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION 'origin operation requires read committed' USING ERRCODE='25001';
    END IF;
    IF tenant IS NULL OR tenant IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'origin context mismatch' USING ERRCODE='42501';
    END IF;
    -- Conservative: reject any pre-held advisory lock, including a session lock.
    -- This avoids C-first composition and permits only one operation per transaction.
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_locks l WHERE l.pid=pg_catalog.pg_backend_pid()
               AND l.locktype='advisory' AND l.granted) THEN
        RAISE EXCEPTION 'origin operation requires no prior advisory lock' USING ERRCODE='40001';
    END IF;
    IF NOT pg_catalog.pg_try_advisory_xact_lock(1330792270,pg_catalog.hashtext(tenant::text)) THEN
        RAISE EXCEPTION 'origin gate busy' USING ERRCODE='40001';
    END IF;
END $function$

CREATE OR REPLACE FUNCTION contour.causal_json_canonical(j jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE typ text:=jsonb_typeof(j); result text;
BEGIN
 IF typ='object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||contour.causal_json_canonical(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO result FROM jsonb_each(j);
 ELSIF typ='array' THEN SELECT '['||coalesce(string_agg(contour.causal_json_canonical(value),',' ORDER BY ord),'')||']' INTO result FROM jsonb_array_elements(j) WITH ORDINALITY a(value,ord);
 ELSE result:=j::text; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION contour.causal_parse(raw bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE j jsonb; e jsonb; prev numeric:=0; seq numeric; ids text[]:='{}'; roots text[]:='{}'; a jsonb; b jsonb; k text;
BEGIN
 IF octet_length(raw) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION 'invalid causal batch size' USING ERRCODE='23514'; END IF;
 j:=convert_from(raw,'UTF8')::jsonb;
 IF convert_to(contour.causal_json_canonical(j),'UTF8')<>raw OR jsonb_typeof(j)<>'object'
 OR j-ARRAY['batch_id','events','first_seq','last_seq','runtime_id','session_epoch','tenant_id','wire_version'] <> '{}'::jsonb
 OR (SELECT count(*) FROM jsonb_object_keys(j))<>8 OR (j->'wire_version')::text IS DISTINCT FROM '1'
 OR NOT contour.causal_u64(j->'session_epoch') OR (j->>'session_epoch')::numeric=0
 OR NOT contour.causal_u64(j->'first_seq') OR NOT contour.causal_u64(j->'last_seq')
 OR jsonb_typeof(j->'events')<>'array' OR jsonb_array_length(j->'events') NOT BETWEEN 1 AND 500
 THEN RAISE EXCEPTION 'invalid causal envelope' USING ERRCODE='23514'; END IF;
 FOREACH k IN ARRAY ARRAY['batch_id','tenant_id','runtime_id'] LOOP
  IF jsonb_typeof(j->k)<>'string' OR length(j->>k)<>36 OR (j->>k COLLATE "C") !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'invalid causal uuid' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(j->'events') LOOP
  k:=e->>'kind';
  IF jsonb_typeof(e)<>'object' OR NOT contour.causal_hex(e->'event_id',32) OR NOT contour.causal_u64(e->'seq') THEN RAISE EXCEPTION 'invalid causal event' USING ERRCODE='23514'; END IF;
  seq:=(e->>'seq')::numeric;
  IF seq<=prev OR e->>'event_id'=ANY(ids) THEN RAISE EXCEPTION 'duplicate causal event' USING ERRCODE='23514'; END IF;
  prev:=seq; ids:=array_append(ids,e->>'event_id');
  IF k='root' THEN
   IF e-ARRAY['kind','event_id','seq','root']<>'{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(e))<>4 OR NOT contour.causal_hex(e->'root',32) OR e->>'root'=ANY(roots) THEN RAISE EXCEPTION 'invalid root' USING ERRCODE='23514'; END IF;
   roots:=array_append(roots,e->>'root');
  ELSIF k='delivery' THEN
   IF e-ARRAY['kind','event_id','seq','root','activity','parent']<>'{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(e))<>6 OR NOT contour.causal_hex(e->'root',32) OR NOT contour.causal_hex(e->'activity',32) OR NOT contour.causal_hex(e->'parent',32) OR e->>'activity'=e->>'parent' THEN RAISE EXCEPTION 'invalid delivery' USING ERRCODE='23514'; END IF;
  ELSIF k='attempt' THEN
   IF e-ARRAY['kind','event_id','seq','root','activity','attempt','marker_digest']<>'{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(e))<>7 OR NOT contour.causal_hex(e->'root',32) OR NOT contour.causal_hex(e->'activity',32) OR NOT contour.causal_hex(e->'attempt',32) OR NOT contour.causal_hex(e->'marker_digest',64) THEN RAISE EXCEPTION 'invalid attempt' USING ERRCODE='23514'; END IF;
  ELSIF k='loss' THEN
   IF e-ARRAY['kind','event_id','seq','first_missing_seq','last_missing_seq','reason']<>'{}'::jsonb OR (SELECT count(*) FROM jsonb_object_keys(e))<>6 OR NOT contour.causal_u64(e->'first_missing_seq') OR NOT contour.causal_u64(e->'last_missing_seq') OR (e->>'first_missing_seq')::numeric=0 OR (e->>'first_missing_seq')::numeric>(e->>'last_missing_seq')::numeric OR (e->>'last_missing_seq')::numeric>=seq OR coalesce(e->>'reason','') NOT IN ('overflow','expired','canceled','guard_invalidated','dispatch_missing','restart','unsupported') THEN RAISE EXCEPTION 'invalid loss' USING ERRCODE='23514'; END IF;
  ELSE RAISE EXCEPTION 'unknown causal event' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF (j->'events'->0->>'seq')::numeric<>(j->>'first_seq')::numeric OR prev<>(j->>'last_seq')::numeric THEN RAISE EXCEPTION 'invalid causal range' USING ERRCODE='23514'; END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(j->'events') LOOP
  FOR b IN SELECT value FROM jsonb_array_elements(j->'events') LOOP
   IF (a->>'kind'='loss' AND (b->>'seq')::numeric BETWEEN (a->>'first_missing_seq')::numeric AND (a->>'last_missing_seq')::numeric)
   OR (a->>'kind'='root' AND b->>'kind'='delivery' AND a->>'root'=b->>'activity')
   OR (a->>'kind'='root' AND b->>'kind'='attempt' AND a->>'root'=b->>'activity' AND b->>'root'<>b->>'activity')
   OR (a->>'kind' IN ('delivery','attempt') AND b->>'kind' IN ('delivery','attempt') AND a->>'activity'=b->>'activity' AND a->>'root'<>b->>'root')
   OR (a->>'kind'='delivery' AND b->>'kind'='delivery' AND a->>'activity'=b->>'activity' AND a->>'parent'<>b->>'parent')
   OR (a->>'kind'='attempt' AND b->>'kind'='attempt' AND a->>'attempt'=b->>'attempt' AND (a->>'root',a->>'activity',a->>'marker_digest')<>(b->>'root',b->>'activity',b->>'marker_digest'))
   THEN RAISE EXCEPTION 'contradictory causal batch' USING ERRCODE='23514'; END IF;
  END LOOP;
 END LOOP;
 RETURN j;
END $function$

CREATE OR REPLACE FUNCTION contour.causal_session_locked(x contour.causal_session_claim, ep numeric, now_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE checked_at timestamptz;
BEGIN
 IF ep IS NULL OR ep<>trunc(ep) OR ep NOT BETWEEN 1 AND 18446744073709551615 THEN RETURN false; END IF;
 PERFORM contour.require_origin_locks(x.tenant_id,x.collector_id,x.export_leaf);
 IF now_at IS NULL OR NOT isfinite(now_at) OR NOT contour.causal_runtime_authority_locked(x,now_at) THEN RETURN false; END IF;
 checked_at:=pg_catalog.clock_timestamp();
 IF checked_at IS NULL OR NOT isfinite(checked_at) OR checked_at<now_at THEN RETURN false; END IF;
 RETURN EXISTS (SELECT 1 FROM contour.causal_sessions s WHERE s.tenant_id=x.tenant_id AND s.runtime_id=x.runtime_id
    AND s.epoch=ep AND s.claim IS NOT DISTINCT FROM x AND s.issued_at<=checked_at AND checked_at<s.expires_at
    AND checked_at>=x.grant_issued AND checked_at<x.grant_expires AND checked_at>=x.policy_issued AND checked_at<x.policy_expires
    AND s.epoch=(SELECT max(y.epoch) FROM contour.causal_sessions y WHERE y.tenant_id=x.tenant_id AND y.runtime_id=x.runtime_id));
END $function$

CREATE OR REPLACE FUNCTION contour.check_origin_pending_batch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE prior text; payload bytea;
BEGIN
    prior := pg_catalog.current_setting('apicontour.tenant_id',true);
    PERFORM pg_catalog.set_config('apicontour.tenant_id',NEW.tenant_id::text,true);
    SELECT p.checked_batch INTO STRICT payload FROM contour.ingestion_payloads p
      WHERE p.tenant_id=NEW.tenant_id AND p.collector_id=NEW.collector_id AND p.batch_id=NEW.batch_id
        AND p.payload_format=2 AND pg_catalog.octet_length(p.checked_batch) BETWEEN 1 AND 1048576;
    PERFORM contour.verify_origin_batch_proofs(NEW.tenant_id,NEW.collector_id,NEW.batch_id,payload);
    DELETE FROM contour.origin_pending_batch p WHERE p.transaction_id=NEW.transaction_id
      AND p.backend_pid=NEW.backend_pid AND p.tenant_id=NEW.tenant_id
      AND p.collector_id=NEW.collector_id AND p.batch_id=NEW.batch_id;
    PERFORM pg_catalog.set_config('apicontour.tenant_id',coalesce(prior,''),true);
    RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION contour.check_public_comparison_inputs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'contour'
AS $function$
DECLARE comparison contour.comparisons; actual bigint; invalid boolean;
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'comparison tenant context required' USING ERRCODE='42501';
    END IF;
    SELECT * INTO comparison FROM contour.comparisons
        WHERE tenant_id=NEW.tenant_id AND comparison_id=NEW.comparison_id;
    SELECT count(*),coalesce(bool_or(
        input_kind IS DISTINCT FROM CASE side WHEN 'left' THEN comparison.left_kind ELSE comparison.right_kind END
        OR version_id IS DISTINCT FROM CASE side WHEN 'left' THEN comparison.left_version_id ELSE comparison.right_version_id END
        OR approval_event_id IS DISTINCT FROM CASE side WHEN 'left' THEN comparison.left_event_id ELSE comparison.right_event_id END
    ),false) INTO actual,invalid FROM contour.public_comparison_inputs
        WHERE tenant_id=NEW.tenant_id AND comparison_id=NEW.comparison_id;
    IF comparison.comparison_id IS NULL OR invalid
        OR actual <> (CASE comparison.public_projection WHEN 1 THEN 0 ELSE 2 END) THEN
        RAISE EXCEPTION 'incomplete or mismatched public comparison inputs' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION contour.check_public_contract_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'contour'
AS $function$
DECLARE expected integer; actual bigint; projection smallint; invalid boolean;
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'contract tenant context required' USING ERRCODE='42501';
    END IF;
    SELECT member_count,projection_version INTO expected,projection
        FROM contour.public_declared_contracts
        WHERE tenant_id=NEW.tenant_id AND contract_id=NEW.contract_id;
    SELECT count(*),coalesce(bool_or(CASE projection
        WHEN 1 THEN body_selector IS NOT NULL OR media_type IS NOT NULL
        WHEN 2 THEN body_selector IS NULL OR media_type IS NULL
        ELSE true END),false) INTO actual,invalid
        FROM contour.public_declared_members
        WHERE tenant_id=NEW.tenant_id AND contract_id=NEW.contract_id;
    IF expected IS NULL OR actual <> expected OR invalid THEN
        RAISE EXCEPTION 'incomplete contract membership' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION contour.cleanup_origin_ingress_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE prior text;
BEGIN
    prior := pg_catalog.current_setting('apicontour.tenant_id', true);
    PERFORM pg_catalog.set_config('apicontour.tenant_id', NEW.tenant_id::text, true);
    DELETE FROM contour.origin_ingress_context c
      WHERE c.transaction_id=NEW.transaction_id AND c.backend_pid=NEW.backend_pid
        AND c.tenant_id=NEW.tenant_id AND c.collector_id=NEW.collector_id;
    PERFORM pg_catalog.set_config('apicontour.tenant_id', coalesce(prior,''), true);
    RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION contour.guard_instance_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    PERFORM contour.guard_collector(NEW.tenant_id, NEW.collector_id);
    IF NOT EXISTS (SELECT 1 FROM contour.sources s WHERE s.tenant_id=NEW.tenant_id
        AND s.source_id=NEW.source_id AND s.binding_mode='instance') THEN
        RAISE EXCEPTION 'source is not instance-bound' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION contour.guard_origin_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE collector uuid;
BEGIN
    IF TG_TABLE_NAME='origin_credentials' THEN
        PERFORM contour.require_origin_locks(NEW.tenant_id,NULL,NEW.leaf_sha256);
    ELSIF TG_TABLE_NAME='origin_observer_grants' THEN
        PERFORM contour.require_origin_locks(NEW.tenant_id,NEW.collector_id,NULL);
    ELSIF TG_TABLE_NAME='origin_terminal_events' THEN
        IF NEW.event_kind='grant_revoked' THEN
            SELECT g.collector_id INTO collector FROM contour.origin_observer_grants g
              WHERE g.tenant_id=NEW.tenant_id AND g.grant_id=NEW.grant_id;
            IF collector IS NULL THEN RAISE EXCEPTION 'grant unavailable' USING ERRCODE='23514'; END IF;
            PERFORM contour.require_origin_locks(NEW.tenant_id,collector,NULL);
        ELSE
            PERFORM contour.require_origin_locks(NEW.tenant_id,NULL,NULL);
        END IF;
    ELSIF TG_TABLE_NAME='origin_lifecycles' THEN
        PERFORM contour.require_origin_locks(NEW.tenant_id,NULL,NULL);
    ELSE
        RAISE EXCEPTION 'unexpected origin registry table' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION contour.lock_origin_credential(leaf bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF leaf IS NULL OR pg_catalog.octet_length(leaf) <> 32 THEN
        RAISE EXCEPTION 'invalid credential' USING ERRCODE='23514';
    END IF;
    IF NOT pg_catalog.pg_try_advisory_xact_lock(1330792271,pg_catalog.hashtext(pg_catalog.encode(leaf,'hex'))) THEN
        RAISE EXCEPTION 'credential gate busy' USING ERRCODE='40001';
    END IF;
END $function$

CREATE OR REPLACE FUNCTION contour.mark_origin_payload_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    NEW.origin_writer_provenance:=false;
    IF NEW.payload_format=2 AND EXISTS (SELECT 1 FROM contour.origin_ingress_context c
      WHERE c.transaction_id=pg_catalog.txid_current() AND c.backend_pid=pg_catalog.pg_backend_pid()
        AND c.tenant_id=NEW.tenant_id AND c.collector_id=NEW.collector_id) THEN
        PERFORM contour.require_origin_ingress(NEW.tenant_id,NEW.collector_id);
        NEW.origin_writer_provenance:=true;
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION contour.origin_history_highwater(tenant uuid, lifecycle uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE history_time timestamptz; floor_time timestamptz;
BEGIN
    history_time := contour.origin_lifecycle_highwater(tenant,lifecycle);
    SELECT s.clock_floor INTO floor_time FROM contour.origin_tenant_state s WHERE s.tenant_id=tenant;
    RETURN greatest(history_time,floor_time);
END $function$

CREATE OR REPLACE FUNCTION contour.parse_origin_batch(tenant uuid, collector uuid, batch uuid, canonical_checked_payload bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE b contour.ingestion_batches; p contour.ingestion_payloads; m contour.ingestion_v2_metadata;
    envelope jsonb; wrapper jsonb; rec jsonb; matches integer; row_count integer; revision numeric;
BEGIN
    IF tenant IS NULL OR tenant IS DISTINCT FROM contour.tenant_context() THEN
        RAISE EXCEPTION 'origin context mismatch' USING ERRCODE='42501';
    END IF;
    IF pg_catalog.octet_length(canonical_checked_payload) NOT BETWEEN 1 AND 1048576 THEN
        RAISE EXCEPTION 'invalid checked payload' USING ERRCODE='23514';
    END IF;
    SELECT x.* INTO STRICT b FROM contour.ingestion_batches x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND x.digest_version=2 AND pg_catalog.octet_length(x.request_digest)=32;
    SELECT x.* INTO STRICT p FROM contour.ingestion_payloads x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND x.payload_format=2 AND pg_catalog.octet_length(x.checked_batch) BETWEEN 1 AND 1048576;
    IF pg_catalog.sha256(pg_catalog.convert_to(E'apicontour/batch/2\n','UTF8') || canonical_checked_payload) IS DISTINCT FROM b.request_digest THEN
        RAISE EXCEPTION 'checked payload digest mismatch' USING ERRCODE='23514';
    END IF;
    envelope := pg_catalog.convert_from(canonical_checked_payload,'UTF8')::jsonb;
    IF p.checked_batch IS DISTINCT FROM canonical_checked_payload OR envelope->>'wire_version' IS DISTINCT FROM '2'
       OR envelope->>'tenant_id' IS DISTINCT FROM tenant::text OR envelope->>'collector_id' IS DISTINCT FROM collector::text
       OR envelope->>'batch_id' IS DISTINCT FROM batch::text OR pg_catalog.jsonb_typeof(envelope->'records') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_array_length(envelope->'records') IS DISTINCT FROM b.record_count OR b.record_count NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION 'checked payload mismatch' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO row_count FROM (
        SELECT 1 FROM contour.ingestion_v2_metadata x
        WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch
        LIMIT 501
    ) bounded_metadata;
    IF row_count IS DISTINCT FROM b.record_count OR NOT pg_catalog.isfinite(b.accepted_at) THEN
        RAISE EXCEPTION 'metadata cardinality mismatch' USING ERRCODE='23514';
    END IF;
    SELECT count(DISTINCT x.value->'record'->>'record_id') INTO matches
      FROM pg_catalog.jsonb_array_elements(envelope->'records') x(value);
    IF matches IS DISTINCT FROM b.record_count THEN
        RAISE EXCEPTION 'duplicate or missing record' USING ERRCODE='23514';
    END IF;
    FOR wrapper IN SELECT x.value FROM pg_catalog.jsonb_array_elements(envelope->'records') x(value) LOOP
        rec := wrapper->'record';
        IF pg_catalog.jsonb_typeof(rec->'policy_revision') IS DISTINCT FROM 'number' THEN
            RAISE EXCEPTION 'invalid record' USING ERRCODE='23514';
        END IF;
        SELECT x.* INTO STRICT m FROM contour.ingestion_v2_metadata x
          WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND x.record_id::text=rec->>'record_id'
            AND pg_catalog.octet_length(x.request_digest)=32 AND pg_catalog.octet_length(x.parser_profile) BETWEEN 1 AND 64
            AND x.attribution_class IN ('unattributed','verified_origin_v1');
        revision := (rec->>'policy_revision')::numeric;
        IF revision < 1 OR revision > 18446744073709551615 OR revision <> pg_catalog.trunc(revision)
           OR m.policy_revision < 1 OR m.policy_revision > 18446744073709551615
           OR m.policy_revision <> pg_catalog.trunc(m.policy_revision) OR m.policy_revision <> revision
           OR rec->>'source_id' IS DISTINCT FROM m.source_id::text OR rec->>'project_id' IS DISTINCT FROM m.project_id::text
           OR rec->>'service_id' IS DISTINCT FROM m.service_id::text OR rec->>'environment_id' IS DISTINCT FROM m.environment_id::text
           OR rec->>'deployment_id' IS DISTINCT FROM m.deployment_id::text OR rec->>'parser_profile' IS DISTINCT FROM m.parser_profile
           OR m.digest_version IS DISTINCT FROM 2 OR m.request_digest IS DISTINCT FROM b.request_digest
           OR m.accepted_at IS DISTINCT FROM b.accepted_at OR NOT pg_catalog.isfinite(m.accepted_at)
           OR (m.attribution_class = 'verified_origin_v1' AND
               (rec IS NULL OR wrapper->'origin_witness'->>'kind' IS DISTINCT FROM 'downstream_mtls_leaf_sha256_v1')) THEN
            RAISE EXCEPTION 'metadata mismatch' USING ERRCODE='23514';
        END IF;
    END LOOP;
    RETURN envelope;
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_text_representation OR character_not_in_repertoire THEN
    RAISE EXCEPTION 'checked batch unavailable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION contour.require_origin_locks(tenant uuid, collector uuid DEFAULT NULL::uuid, leaf bytea DEFAULT NULL::bytea)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF pg_catalog.current_setting('transaction_isolation') <> 'read committed'
        OR tenant IS NULL OR tenant IS DISTINCT FROM contour.tenant_context()
        OR NOT contour.origin_lock_held(1330792270,pg_catalog.hashtext(tenant::text)) THEN
        RAISE EXCEPTION 'origin gate required' USING ERRCODE='42501';
    END IF;
    IF collector IS NOT NULL AND NOT contour.origin_collector_lock_held(tenant,collector) THEN
        RAISE EXCEPTION 'collector gate required' USING ERRCODE='42501';
    END IF;
    IF leaf IS NOT NULL AND (pg_catalog.octet_length(leaf) <> 32 OR NOT contour.origin_lock_held(1330792271,pg_catalog.hashtext(pg_catalog.encode(leaf,'hex')))) THEN
        RAISE EXCEPTION 'credential gate required' USING ERRCODE='42501';
    END IF;
END $function$

CREATE OR REPLACE FUNCTION contour.reserve_product_leaf()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 PERFORM contour.require_origin_locks(NEW.tenant_id,NULL,NEW.leaf_sha256);
 INSERT INTO contour.causal_leaf_reservations VALUES (NEW.leaf_sha256,'product');
 RETURN NEW;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'leaf unavailable' USING ERRCODE='23505';
END $function$

CREATE OR REPLACE FUNCTION contour.resolve_origin_record_checked(tenant uuid, collector uuid, m contour.ingestion_v2_metadata, witness jsonb)
 RETURNS contour.origin_resolution
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE result contour.origin_resolution; leaf bytea; now_time timestamptz; ctx contour.origin_ingress_context; floor_time timestamptz;
BEGIN
    PERFORM contour.require_origin_ingress(tenant,collector);
    IF m.tenant_id IS DISTINCT FROM tenant OR m.collector_id IS DISTINCT FROM collector
       OR witness->>'kind' IS DISTINCT FROM 'downstream_mtls_leaf_sha256_v1'
       OR pg_catalog.jsonb_typeof(witness) IS DISTINCT FROM 'object'
       OR witness->>'leaf_sha256' IS NULL OR (witness->>'leaf_sha256') COLLATE "C" !~ '^[0-9a-f]{64}$'
       OR witness - 'kind' - 'leaf_sha256' <> '{}'::jsonb THEN
        RAISE EXCEPTION 'origin witness unavailable' USING ERRCODE='23514';
    END IF;
    leaf := pg_catalog.decode(witness->>'leaf_sha256','hex');
    SELECT c.* INTO STRICT ctx FROM contour.origin_ingress_context c
      WHERE c.transaction_id=pg_catalog.txid_current() AND c.backend_pid=pg_catalog.pg_backend_pid()
        AND c.tenant_id=tenant AND c.collector_id=collector;
    SELECT s.clock_floor INTO floor_time FROM contour.origin_tenant_state s WHERE s.tenant_id=tenant;
    now_time := contour.origin_server_time();
    IF now_time IS NULL OR NOT pg_catalog.isfinite(now_time) OR now_time < ctx.started_at
       OR (floor_time IS NOT NULL AND now_time < floor_time) OR now_time < m.accepted_at THEN
        RAISE EXCEPTION 'invalid clock' USING ERRCODE='23514';
    END IF;
    BEGIN
    SELECT l.lifecycle_id,c.credential_id,g.grant_id,l.project_id,l.service_id,l.environment_id,
        l.deployment_id,l.instance_id,l.platform_evidence_sha256,l.fact_epoch,c.fact_epoch,g.fact_epoch,
        ctx.fact_epoch,ctx.started_at
      INTO STRICT result
      FROM contour.origin_credentials c
      JOIN contour.origin_lifecycles l ON l.tenant_id=c.tenant_id AND l.lifecycle_id=c.lifecycle_id
      JOIN contour.origin_observer_grants g ON g.tenant_id=l.tenant_id AND g.lifecycle_id=l.lifecycle_id
      WHERE c.tenant_id=tenant AND c.leaf_sha256=leaf
        AND g.source_id=m.source_id AND g.collector_id=collector AND g.project_id=m.project_id
        AND g.service_id=m.service_id AND g.environment_id=m.environment_id AND g.deployment_id=m.deployment_id
        AND l.enrolled_at<=m.accepted_at AND c.enrolled_at<=m.accepted_at AND g.granted_at<=m.accepted_at
        AND l.fact_epoch<=ctx.fact_epoch AND c.fact_epoch<=ctx.fact_epoch AND g.fact_epoch<=ctx.fact_epoch
        AND NOT EXISTS (SELECT 1 FROM contour.origin_terminal_events e WHERE e.tenant_id=tenant AND
          ((e.event_kind='lifecycle_closed' AND e.lifecycle_id=l.lifecycle_id)
           OR (e.event_kind='credential_revoked' AND e.credential_id=c.credential_id)
           OR (e.event_kind='grant_revoked' AND e.grant_id=g.grant_id)));
    EXCEPTION WHEN no_data_found THEN
        RAISE EXCEPTION 'origin unavailable' USING ERRCODE='23514', CONSTRAINT='origin_live_resolution_unavailable';
    END;
    RETURN result;
EXCEPTION WHEN no_data_found OR too_many_rows THEN
    RAISE EXCEPTION 'origin unavailable' USING ERRCODE='23514';
END $function$

CREATE OR REPLACE FUNCTION contour.verify_origin_batch_parsed(tenant uuid, collector uuid, batch uuid, b contour.ingestion_batches, envelope jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE wrapper jsonb; witness jsonb; m contour.ingestion_v2_metadata; p contour.origin_proofs;
    completion contour.origin_batch_proof_completion; has_completion boolean;
    expected integer; actual integer; set_digest bytea;
BEGIN
    -- First classify the complete checked batch. A zero-fingerprint batch needs
    -- no marker: its immutable canonical digest cannot later gain a witness.
    expected := 0;
    FOR wrapper IN SELECT x.value FROM pg_catalog.jsonb_array_elements(envelope->'records') x(value) LOOP
        witness := wrapper->'origin_witness';
        IF witness = '{"kind":"unattributed"}'::jsonb THEN CONTINUE; END IF;
        IF pg_catalog.jsonb_typeof(witness) IS DISTINCT FROM 'object'
           OR witness->>'kind' IS DISTINCT FROM 'downstream_mtls_leaf_sha256_v1'
           OR (witness->>'leaf_sha256') COLLATE "C" !~ '^[0-9a-f]{64}$'
           OR witness->>'leaf_sha256' IS NULL OR witness - 'kind' - 'leaf_sha256' <> '{}'::jsonb THEN
            RAISE EXCEPTION 'origin witness unavailable' USING ERRCODE='23514';
        END IF;
        expected := expected+1;
    END LOOP;
    SELECT x.* INTO completion FROM contour.origin_batch_proof_completion x
      WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch
        AND pg_catalog.octet_length(x.request_digest)=32 AND pg_catalog.octet_length(x.proof_set_digest)=32;
    has_completion := FOUND;
    IF NOT has_completion AND EXISTS (SELECT 1 FROM contour.origin_batch_proof_completion x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch) THEN
        RAISE EXCEPTION 'origin completion mismatch' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO actual FROM (SELECT 1 FROM contour.origin_proofs x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch LIMIT 501) bounded_proofs;
    IF has_completion THEN
        IF completion.request_digest IS DISTINCT FROM b.request_digest OR completion.receipt_id IS DISTINCT FROM b.receipt_id
           OR completion.accepted_at IS DISTINCT FROM b.accepted_at OR NOT pg_catalog.isfinite(completion.accepted_at)
           OR completion.proof_count IS DISTINCT FROM expected OR actual IS DISTINCT FROM expected OR expected NOT BETWEEN 1 AND 500
           OR EXISTS (SELECT 1 FROM contour.origin_proofs x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch
             AND (pg_catalog.octet_length(x.canonical_proof) NOT BETWEEN 1 AND 4096 OR pg_catalog.octet_length(x.request_digest)<>32
                  OR pg_catalog.octet_length(x.leaf_sha256)<>32 OR pg_catalog.octet_length(x.platform_evidence_sha256)<>32
                  OR pg_catalog.octet_length(x.parser_profile) NOT BETWEEN 1 AND 64)) THEN
            RAISE EXCEPTION 'origin completion mismatch' USING ERRCODE='23514';
        END IF;
        set_digest := contour.origin_proof_set_digest(tenant,collector,batch);
        IF set_digest IS DISTINCT FROM completion.proof_set_digest THEN
            RAISE EXCEPTION 'origin completion mismatch' USING ERRCODE='23514';
        END IF;
    ELSIF actual <> 0 OR expected <> 0 THEN
        RAISE EXCEPTION 'origin completion missing' USING ERRCODE='23514';
    ELSE
        RETURN 0;
    END IF;
    FOR wrapper IN SELECT x.value FROM pg_catalog.jsonb_array_elements(envelope->'records') x(value) LOOP
        witness := wrapper->'origin_witness';
        IF witness = '{"kind":"unattributed"}'::jsonb THEN
            IF EXISTS (SELECT 1 FROM contour.origin_proofs x WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND x.record_id::text=wrapper->'record'->>'record_id') THEN
                RAISE EXCEPTION 'unexpected origin proof' USING ERRCODE='23514';
            END IF;
            CONTINUE;
        END IF;
        SELECT x.* INTO STRICT m FROM contour.ingestion_v2_metadata x
          WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND x.record_id::text=wrapper->'record'->>'record_id'
            AND pg_catalog.octet_length(x.request_digest)=32 AND pg_catalog.octet_length(x.parser_profile) BETWEEN 1 AND 64 AND x.attribution_class IN ('unattributed','verified_origin_v1');
        SELECT x.* INTO STRICT p FROM contour.origin_proofs x
          WHERE x.tenant_id=tenant AND x.collector_id=collector AND x.batch_id=batch AND x.record_id=m.record_id
            AND pg_catalog.octet_length(x.canonical_proof) BETWEEN 1 AND 4096
            AND pg_catalog.octet_length(x.request_digest)=32 AND pg_catalog.octet_length(x.leaf_sha256)=32
            AND pg_catalog.octet_length(x.platform_evidence_sha256)=32 AND pg_catalog.octet_length(x.parser_profile) BETWEEN 1 AND 64;
        PERFORM contour.verify_origin_proof_parsed(tenant,p,b,m,wrapper);
    END LOOP;
    RETURN expected;
EXCEPTION WHEN no_data_found OR too_many_rows OR invalid_text_representation OR character_not_in_repertoire THEN
    RAISE EXCEPTION 'origin batch unavailable' USING ERRCODE='23514';
END $function$
